import java.util.Arrays;

public class Main {
    static void moveZeros(int[] a) {
        int pos = 0;
        for (int i = 0; i < a.length; i++) {
            if (a[i] != 0) {
                a[pos++] = a[i];
            }
        }
        while (pos < a.length) {
            a[pos++] = 0;
        }
    }

    public static void main(String[] args) {
        int[] a = {0, 1, 0, 3, 12};
        moveZeros(a);
        System.out.println(Arrays.toString(a));
    }
}
